using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class SaintChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){var old=new SliceState();string before=JsonUtility.ToJson(old);CulturalBookText.Read(old,0,null);Require(before==JsonUtility.ToJson(old)&&old.culture==null,"Lore invented old history");var b=new SaintBelief();b.Witness(0,1,.2f);Require(b.Valid()&&b.confidence>.5f,"Witness failed");float confidence=b.confidence;b.Witness(0,1,1);Require(b.confidence==confidence,"Duplicate survival reinforced belief");var rumor=new SaintBelief();for(int i=0;i<4;i++)rumor.Hear(0);Require(rumor.confidence>=.5f&&rumor.Valid(),"Repeated heard stories do not change belief");b.chosen=99;Require(!b.Valid(),"Invalid chosen identity accepted");Debug.Log("BWVR_SAINT_MODEL_PASS");}
 public static void Verify(){
  Require(Application.isPlaying,"Enter Play mode");VerifyModel();var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var god=slice.GetComponentInChildren<CreatureHybrid>();var nav=god.GetComponent<IslandNavigator>().world;Require(!nav.TreeNavigationPending,"Wait for navigation");var people=slice.GetComponentsInChildren<VillagerSocial>();var positions=people.Select(p=>p.transform.position).ToArray();var rotations=people.Select(p=>p.transform.rotation).ToArray();var field=typeof(QuestSlice).GetField("state",Flags);var original=field.GetValue(slice);var chapter=slice.Chapter;var godAt=god.transform.position;var weather=slice.GetComponentInChildren<IslandWeather>();bool automatic=weather.automatic;var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true,water=100};test.Hybrid.time=100;var visitor=people[1].GetComponent<VillagerExploration>();
  try{
   god.Interrupt("Saint QA");god.transform.position+=Vector3.up*nav.Scale*500;foreach(var p in people){p.ResetTask();p.GetComponent<VillagerExploration>().ResetTask();p.GetComponent<VillagerResourceGathering>().Cancel();p.GetComponent<VillagerBlockPlay>().ResetTask();p.transform.position+=Vector3.up*nav.Scale*500;}field.SetValue(slice,test);slice.GetComponentInChildren<VillageFamilies>().ResetWorld();var lane=slice.GetComponentInChildren<BeachBall>().Bowling;Require(nav.Sample(lane.Start,nav.villager,8,out var foot),"No survivor staging point");people[0].transform.position=nav.ProjectFoot(foot,nav.villager);test.stormChapter=new StormChapterState{phase=StormPhase.Storm,episode=1,opportunity=true,villager=0,refuge=nav.ToNav(people[0].transform.position),actorPoint=nav.ToNav(people[0].transform.position)};chapter.Advance(0,false);var resources=slice.GetComponentInChildren<VillageResources>();bool visible=false;
   for(int i=0;i<24;i++){var wanted=people[0].transform.position+Quaternion.Euler(0,i*15,0)*Vector3.forward*nav.Scale*8;if(!nav.Sample(wanted,nav.villager,4,out var at))continue;people[1].transform.position=nav.ProjectFoot(at,nav.villager);people[1].transform.LookAt(new Vector3(people[0].transform.position.x,people[1].transform.position.y,people[0].transform.position.z));Physics.SyncTransforms();if(resources.ProvisionVisible(people[1],people[0].transform.position,people[0].transform)){visible=true;break;}}
   Require(visible,"No witnessed survivor stage: survivor="+people[0].transform.position+" witness="+people[1].transform.position+" held="+people[1].GetComponent<CarryItem>().held+" target collider="+people[0].GetComponent<Collider>().enabled+" bounds="+people[0].GetComponent<Collider>().bounds+" enabled="+people[1].isActiveAndEnabled);test.paused=true;Require(!chapter.Confirm(RescueSource.Independent)&&test.culture==null,"Paused event created story");test.paused=false;Require(chapter.Confirm(RescueSource.Independent)&&test.culture.saintStories==1&&people[1].Memory.saint?.chosen==0&&people[2].Memory.saint==null,"Native safe arrival did not separate witnesses and distant villagers");string memory=JsonUtility.ToJson(test);Require(!chapter.Confirm(RescueSource.Player)&&memory==JsonUtility.ToJson(test),"Duplicate safe arrival created another story");
   Require((bool)typeof(VillagerExploration).GetMethod("TrySaintVisit",Flags).Invoke(visitor,null),"Believer refused native visit");var phase=visitor.Current;visitor.Tick(5,true);Require(visitor.Current==phase&&people[1].Memory.saint.visits==0,"Paused visit completed");for(int i=0;i<600&&people[1].Memory.saint.visits==0;i++){test.Hybrid.time+=.05f;visitor.Tick(.05f,false);}Require(people[1].Memory.saint.visits==1&&visitor.Current==VillagerExploration.Phase.Celebrate,"Believer did not physically approach and greet survivor");visitor.ResetTask();Require(!(bool)typeof(VillagerExploration).GetMethod("TrySaintVisit",Flags).Invoke(visitor,null),"Saint visit cooldown ignored");
   var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(test));Require(saved.Valid()&&saved.relationships[1].saint.visits==1&&CulturalBookText.Read(saved,0,null).text.Contains("1 completed visits"),"Chosen survivor story did not save / read truthfully");saved.relationships[1].saint.confidence=float.NaN;Require(!saved.Valid(),"Invalid conviction accepted");Debug.Log("BWVR_SAINT_RUNTIME_PASS: native safe-arrival hook, real witnessed belief, unseen/paused/duplicate exclusion, autonomous visit motor, cooldown, saved story and pure Lore");
  }finally{foreach(var p in people)p.GetComponent<VillagerExploration>().ResetTask();chapter.Stop();field.SetValue(slice,original);chapter.Advance(0,true);weather.automatic=automatic;for(int i=0;i<people.Length;i++){people[i].transform.SetPositionAndRotation(positions[i],rotations[i]);people[i].GetComponent<IslandNavigator>().ResetRoute();}god.Interrupt("Saint QA complete");god.transform.position=godAt;god.GetComponent<IslandNavigator>().ResetRoute();}
 }
}
}
